function assetPut(m,blob){return new Promise((resolve,reject)=>{const tx=ui.db.transaction(['assets','meta'],'readwrite');const meta={url:m.url,bytes:blob.size,type:blob.type,savedAt:Date.now()};tx.objectStore('assets').put(blob,m.url);tx.objectStore('meta').put(meta);tx.oncomplete=()=>{ui.cache.set(m.url,meta);resolve();};tx.onerror=()=>reject(tx.error||new Error('Not enough storage to save this file.'));tx.onabort=()=>reject(tx.error||new Error('The file could not be saved.'));});}
