 if(response.body?.getReader){const reader=response.body.getReader(),chunks=[];let bytes=0;while(true){const {done,value}=await reader.read();if(done)break;chunks.push(value);bytes+=value.length;if(ui.preparing)progressUpdate(`Saving ${m.title} · ${formatBytes(bytes)}`,ui.progress?.done||0,ui.progress?.total||1);}blob=new Blob(chunks,{type:m.type||type});}
